 public function __construct(private NumberingService$numbering,private GlPostingService$gl,private AuditService$audit,private FinanceTaxService$taxes,private FxRateService$fx){}
 public function createArInvoiceFromShipment(Shipment$shipment,User$user,?string$dueDate=null,array$taxInputs=[]):ArInvoice{return DB::transaction(function()use($shipment,$user,$dueDate,$taxInputs){$locked=Shipment::withoutGlobalScopes()->with('lines')->whereKey($shipment->id)->lockForUpdate()->firstOrFail();$this->assertAccess($user,(int)$locked->company_id);if($locked->status!=='SHIPPED')throw new RuntimeException('AR invoice hanya dari shipment SHIPPED.');$existing=ArInvoice::withoutGlobalScopes()->where('shipment_id',$locked->id)->where('status','!=','VOID')->first();if($existing)return$existing->load('lines','taxLines');$so=SalesOrder::withoutGlobalScopes()->with('lines')->where('company_id',$locked->company_id)->whereKey($locked->sales_order_id)->lockForUpdate()->firstOrFail();$invoiceDate=now();$rate=$this->fx->resolve((int)$locked->company_id,$so->currency_id,$invoiceDate->toDateString(),$so->exchange_rate??null);$payload=[];$subtotal=0.0;foreach($locked->lines as$line){$soLine=$so->lines->first(fn($x)=>(int)$x->style_id===(int)$line->style_id&&(int)$x->colorway_id===(int)$line->colorway_id&&(int)$x->size_id===(int)$line->size_id);if(!$soLine||(float)$soLine->price<=0)throw new RuntimeException('Harga SO matrix shipment tidak valid.');$amount=round((float)$line->qty_shipped*(float)$soLine->price,4);$subtotal+=$amount;$payload[]=['style_id'=>$line->style_id,'description'=>"Shipment {$locked->doc_no} — style #{$line->style_id}",'qty'=>(float)$line->qty_shipped,'unit_price'=>(float)$soLine->price,'amount'=>$amount];}$calc=$this->taxes->calculate((int)$locked->company_id,'AR_INVOICE',$subtotal,$taxInputs);$due=$dueDate?Carbon::createFromFormat('Y-m-d',$dueDate):null;if($due&&$due->lt($invoiceDate->copy()->startOfDay()))throw new RuntimeException('Due date AR tidak boleh sebelum invoice date.');$invoice=ArInvoice::create(['company_id'=>$locked->company_id,'doc_no'=>$this->numbering->next($locked->company_id,'INV'),'customer_id'=>$so->customer_id,'sales_order_id'=>$so->id,'shipment_id'=>$locked->id,'invoice_date'=>$invoiceDate->toDateString(),'due_date'=>$due?->toDateString(),'currency_id'=>$so->currency_id,'exchange_rate'=>$rate,'subtotal_amount'=>$calc['subtotal'],'tax_amount'=>$calc['tax'],'withholding_amount'=>$calc['withholding'],'total_amount'=>$calc['total'],'base_amount'=>round($calc['total']*$rate,4),'finance_finalized_at'=>now(),'paid_amount'=>0,'status'=>'OPEN','created_by'=>$user->id]);foreach($payload as$line)$invoice->lines()->create($line);$this->taxes->store('AR_INVOICE',$invoice->id,$calc['lines'],$user->id);$period=$invoiceDate->format('Y-m');$this->gl->postEvent($locked->company_id,'AR_INVOICE','ar_invoices',$invoice->id,round($subtotal*$rate,4),$period,$user,"AR Invoice {$invoice->doc_no}");if($calc['tax']>0)$this->gl->postEvent($locked->company_id,'AR_TAX','ar_invoices',$invoice->id,round($calc['tax']*$rate,4),$period,$user,"Output tax {$invoice->doc_no}");if($calc['withholding']>0)$this->gl->postEvent($locked->company_id,'AR_WITHHOLDING','ar_invoices',$invoice->id,round($calc['withholding']*$rate,4),$period,$user,"Withholding receivable {$invoice->doc_no}");$this->audit->record('create',$invoice,after:['subtotal'=>$calc['subtotal'],'tax'=>$calc['tax'],'withholding'=>$calc['withholding'],'total'=>$calc['total'],'rate'=>$rate]);return$invoice->load('lines','taxLines');});}
 public function finalizeApFinance(SupplierInvoice$invoice,array$data,User$user):SupplierInvoice{return DB::transaction(function()use($invoice,$data,$user){$locked=SupplierInvoice::withoutGlobalScopes()->with('lines')->whereKey($invoice->id)->lockForUpdate()->firstOrFail();$this->assertAccess($user,(int)$locked->company_id);if($locked->status!=='APPROVED'||$locked->match_status!=='MATCHED')throw new RuntimeException('AP finance hanya dapat difinalisasi setelah MATCHED dan APPROVED.');if($locked->finance_finalized_at||FinanceTaxLine::withoutGlobalScopes()->where('document_type','AP_INVOICE')->where('document_id',$locked->id)->exists())throw new RuntimeException('Finance snapshot AP invoice sudah difinalisasi.');if(ApPayment::withoutGlobalScopes()->where('supplier_invoice_id',$locked->id)->exists())throw new RuntimeException('AP invoice yang sudah dibayar tidak dapat difinalisasi ulang.');$subtotal=(float)$locked->lines->sum('amount');if($subtotal<=0)$subtotal=(float)$locked->total_amount;$currencyId=$data['currency_id']??$locked->currency_id??$locked->purchaseOrder?->currency_id;$rate=$this->fx->resolve((int)$locked->company_id,$currencyId,$locked->invoice_date->toDateString(),$data['exchange_rate']??$locked->exchange_rate??null);$calc=$this->taxes->calculate((int)$locked->company_id,'AP_INVOICE',$subtotal,$data['taxes']??[]);$locked->update(['currency_id'=>$currencyId,'exchange_rate'=>$rate,'subtotal_amount'=>$calc['subtotal'],'tax_amount'=>$calc['tax'],'withholding_amount'=>$calc['withholding'],'total_amount'=>$calc['total'],'base_amount'=>round($calc['total']*$rate,4),'finance_finalized_at'=>now(),'updated_by'=>$user->id]);$this->taxes->store('AP_INVOICE',$locked->id,$calc['lines'],$user->id);$period=$locked->invoice_date->format('Y-m');if($calc['tax']>0)$this->gl->postEvent($locked->company_id,'AP_TAX','supplier_invoices',$locked->id,round($calc['tax']*$rate,4),$period,$user,"Input tax {$locked->doc_no}");if($calc['withholding']>0)$this->gl->postEvent($locked->company_id,'AP_WITHHOLDING','supplier_invoices',$locked->id,round($calc['withholding']*$rate,4),$period,$user,"Withholding payable {$locked->doc_no}");$this->audit->record('update',$locked,after:['finance_finalized'=>true,'subtotal'=>$calc['subtotal'],'tax'=>$calc['tax'],'withholding'=>$calc['withholding'],'rate'=>$rate]);return$locked->fresh('taxLines');});}
 public function recordArPayment(ArInvoice$invoice,array$data,User$user):ArPayment{return DB::transaction(function()use($invoice,$data,$user){$locked=ArInvoice::withoutGlobalScopes()->whereKey($invoice->id)->lockForUpdate()->firstOrFail();$this->assertAccess($user,(int)$locked->company_id);if(in_array($locked->status,['PAID','VOID'],true))throw new RuntimeException("Invoice {$locked->doc_no} berstatus {$locked->status}.");$amount=(float)($data['amount']??0);$outstanding=$locked->outstanding();if($amount<=0||$amount>$outstanding+0.0001)throw new RuntimeException("Amount {$amount} tidak valid (outstanding: {$outstanding}).");$date=Carbon::createFromFormat('Y-m-d',$data['payment_date']??now()->toDateString());if($date->lt($locked->invoice_date))throw new RuntimeException('Tanggal pembayaran tidak boleh sebelum tanggal invoice.');$rate=$this->fx->resolve((int)$locked->company_id,$locked->currency_id,$date->toDateString(),$data['exchange_rate']??null);$base=round($amount*$rate,4);$carrying=round($amount*(float)$locked->exchange_rate,4);$realized=round($base-$carrying,4);$payment=ArPayment::create(['company_id'=>$locked->company_id,'doc_no'=>$this->numbering->next($locked->company_id,'PAY'),'ar_invoice_id'=>$locked->id,'payment_date'=>$date->toDateString(),'currency_id'=>$locked->currency_id,'exchange_rate'=>$rate,'amount'=>$amount,'base_amount'=>$base,'realized_fx_amount'=>$realized,'method'=>$data['method']??null,'reference_no'=>$data['reference_no']??null,'created_by'=>$user->id]);$locked->paid_amount=(float)$locked->paid_amount+$amount;$locked->status=$locked->outstanding()<=0.0001?'PAID':'PARTIAL';$locked->save();$period=$date->format('Y-m');$this->gl->postEvent($locked->company_id,'AR_PAYMENT','ar_payments',$payment->id,$base,$period,$user,"Payment {$payment->doc_no}");$this->postFx('AR',$realized,$locked->company_id,'ar_payments',$payment->id,$period,$user,$payment->doc_no);$this->audit->record('create',$payment,after:['amount'=>$amount,'settlement_rate'=>$rate,'base_amount'=>$base,'realized_fx'=>$realized]);return$payment;});}
 public function recordApPayment(SupplierInvoice$invoice,array$data,User$user):ApPayment{return DB::transaction(function()use($invoice,$data,$user){$locked=SupplierInvoice::withoutGlobalScopes()->whereKey($invoice->id)->lockForUpdate()->firstOrFail();$this->assertAccess($user,(int)$locked->company_id);if($locked->match_status!=='MATCHED'||$locked->status!=='APPROVED')throw new RuntimeException("BR-050: invoice {$locked->doc_no} belum MATCHED dan APPROVED.");if(!$locked->finance_finalized_at)$this->finalizeLegacyAp($locked,$user);$locked=$locked->fresh();$paid=(float)ApPayment::withoutGlobalScopes()->where('supplier_invoice_id',$locked->id)->sum('amount');$outstanding=(float)$locked->total_amount-$paid;$amount=(float)($data['amount']??0);if($amount<=0||$amount>$outstanding+0.0001)throw new RuntimeException("Amount {$amount} tidak valid (outstanding: {$outstanding}).");$date=Carbon::createFromFormat('Y-m-d',$data['payment_date']??now()->toDateString());if($date->lt($locked->invoice_date))throw new RuntimeException('Tanggal pembayaran tidak boleh sebelum tanggal invoice.');$rate=$this->fx->resolve((int)$locked->company_id,$locked->currency_id,$date->toDateString(),$data['exchange_rate']??null);$base=round($amount*$rate,4);$carrying=round($amount*(float)$locked->exchange_rate,4);$realized=round($carrying-$base,4);$payment=ApPayment::create(['company_id'=>$locked->company_id,'doc_no'=>$this->numbering->next($locked->company_id,'PAY'),'supplier_invoice_id'=>$locked->id,'payment_date'=>$date->toDateString(),'currency_id'=>$locked->currency_id,'exchange_rate'=>$rate,'amount'=>$amount,'base_amount'=>$base,'realized_fx_amount'=>$realized,'method'=>$data['method']??null,'reference_no'=>$data['reference_no']??null,'created_by'=>$user->id]);if($amount>=$outstanding-0.0001)$locked->update(['status'=>'PAID','updated_by'=>$user->id]);$period=$date->format('Y-m');$this->gl->postEvent($locked->company_id,'AP_PAYMENT','ap_payments',$payment->id,$base,$period,$user,"AP Payment {$payment->doc_no}");$this->postFx('AP',$realized,$locked->company_id,'ap_payments',$payment->id,$period,$user,$payment->doc_no);$this->audit->record('create',$payment,after:['amount'=>$amount,'settlement_rate'=>$rate,'base_amount'=>$base,'realized_fx'=>$realized]);return$payment;});}
 private function finalizeLegacyAp(SupplierInvoice$invoice,User$user):void{$currencyId=$invoice->currency_id;$rate=$this->fx->resolve((int)$invoice->company_id,$currencyId,$invoice->invoice_date->toDateString(),$invoice->exchange_rate?:null);$invoice->update(['exchange_rate'=>$rate,'subtotal_amount'=>$invoice->total_amount,'tax_amount'=>0,'withholding_amount'=>0,'base_amount'=>round((float)$invoice->total_amount*$rate,4),'finance_finalized_at'=>now(),'updated_by'=>$user->id]);}
 private function postFx(string$side,float$realized,int$company,string$type,int$id,string$period,User$user,string$doc):void{if(abs($realized)<=0.0001)return;$event=$side.'_FX_'.($realized>0?'GAIN':'LOSS');$this->gl->postEvent($company,$event,$type,$id,abs($realized),$period,$user,"Realized FX {$doc}");}
 public function agingAr(int$c,string$a):array{$i=ArInvoice::withoutGlobalScopes()->where('company_id',$c)->whereIn('status',['OPEN','PARTIAL'])->get();return$this->bucketize($i->map(fn($x)=>['party'=>$x->customer->name??(string)$x->customer_id,'doc_no'=>$x->doc_no,'due_date'=>$x->due_date??$x->invoice_date,'outstanding'=>$x->outstanding()])->all(),$a);}public function agingAp(int$c,string$a):array{$i=SupplierInvoice::withoutGlobalScopes()->where('company_id',$c)->whereIn('status',['DRAFT','SUBMITTED','APPROVED'])->where('match_status','MATCHED')->get();return$this->bucketize($i->map(function($x){$p=(float)ApPayment::withoutGlobalScopes()->where('supplier_invoice_id',$x->id)->sum('amount');return['party'=>$x->supplier->name??(string)$x->supplier_id,'doc_no'=>$x->doc_no,'due_date'=>$x->due_date??$x->invoice_date,'outstanding'=>(float)$x->total_amount-$p];})->all(),$a);}private function bucketize(array$i,string$a):array{$as=Carbon::createFromFormat('Y-m-d',$a)->startOfDay();$b=['current'=>[],'1_30'=>[],'31_60'=>[],'61_90'=>[],'over_90'=>[]];foreach($i as$x){if($x['outstanding']<=0)continue;$d=Carbon::parse($x['due_date'])->startOfDay();$days=$d->lt($as)?$d->diffInDays($as):0;$k=$days===0?'current':($days<=30?'1_30':($days<=60?'31_60':($days<=90?'61_90':'over_90')));$b[$k][]=$x+['days_past_due'=>$days];}return$b;}private function assertAccess(User$u,int$c):void{if((int)$u->company_id!==$c&&!$u->companies()->whereKey($c)->exists())throw new RuntimeException('User tidak memiliki akses ke company Finance.');}
